create table if not exists public.historical_boq_rates (
  id bigint generated by default as identity primary key,
  description text not null,
  unit text not null,
  rate numeric(14,2) not null check (rate > 0),
  category text not null,
  province_code text not null,
  supplier text not null,
  quote_date date not null,
  source_reference text not null,
  page_reference text not null,
  price_basis text not null,
  status text not null default 'pending' check (status in ('reviewed','pending','rejected')),
  created_at timestamptz not null default now(),
  unique (description, unit, rate, source_reference, page_reference)
);

alter table public.historical_boq_rates enable row level security;
revoke all on public.historical_boq_rates from anon;
grant select on public.historical_boq_rates to authenticated;

drop policy if exists "Authenticated users can read reviewed historical rates" on public.historical_boq_rates;
create policy "Authenticated users can read reviewed historical rates"
  on public.historical_boq_rates for select to authenticated
  using (status = 'reviewed');

create index if not exists historical_boq_rates_lookup_idx
  on public.historical_boq_rates (status, province_code, unit);

on conflict do nothing;

comment on table public.historical_boq_rates is
  'Private reviewed historical quotations used as priority-1 BOQ matching evidence; source documents are not stored or redistributed.';
